func (this *Bitflyer) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//     {
	//         "id": 100,
	//         "order_id": "CDP20151227-024141-055555",
	//         "currency_code": "BTC",
	//         "amount": 0.00002,
	//         "address": "1WriteySQufKZ2pVuM1oMhPrTtTVFq35j",
	//         "tx_hash": "9f92ee65a176bb9545f7becb8706c50d07d4cee5ffca34d8be3ef11d411405ae",
	//         "status": "COMPLETED",
	//         "event_date": "2015-11-27T08:59:20.301"
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "id": 500,
	//         "order_id": "CWD20151224-014040-077777",
	//         "currency_code": "BTC",
	//         "amount": 0.1234,
	//         "address": "1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa",
	//         "tx_hash": "724c07dfd4044abcb390b0412c3e707dd5c4f373f0a52b3bd295ce32b478c60a",
	//         "fee": 0.0005,
	//         "additional_fee": 0.0001,
	//         "status": "COMPLETED",
	//         "event_date": "2015-12-24T01:40:40.397"
	//     }
	//
	// withdraw
	//
	//     {
	//         "message_id": "69476620-5056-4003-bcbe-42658a2b041b"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var id any = this.SafeString2(transaction, "id", "message_id")
	var address any = this.SafeString(transaction, "address")
	var currencyId any = this.SafeString(transaction, "currency_code")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	var timestamp any = this.Parse8601(this.SafeString(transaction, "event_date"))
	var amount any = this.SafeNumber(transaction, "amount")
	var txId any = this.SafeString(transaction, "tx_hash")
	var rawStatus any = this.SafeString(transaction, "status")
	var typeVar any = nil
	var status any = nil
	var fee any = nil
	if IsTrue(InOp(transaction, "fee")) {
		typeVar = "withdrawal"
		status = this.ParseWithdrawalStatus(rawStatus)
		var feeCost any = this.SafeString(transaction, "fee")
		var additionalFee any = this.SafeString(transaction, "additional_fee")
		fee = map[string]any{
			"currency": code,
			"cost":     this.ParseNumber(Precise.StringAdd(feeCost, additionalFee)),
		}
	} else {
		typeVar = "deposit"
		status = this.ParseDepositStatus(rawStatus)
	}
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txId,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      amount,
		"currency":    code,
		"status":      status,
		"updated":     nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
	}
}

